const lessons=[{"id": 0, "title": "命题与集合", "start": 1, "end": 21, "group": "逻辑与集合", "intro": "把自然语言变成可计算的表达式。命题是能判断真假的陈述句；集合由确定的、互异的元素组成。", "formula": "p → q ≡ ¬p ∨ q；|P(A)| = 2^|A|", "body": "蕴含只有在前件真、后件假时为假。集合运算先辨明元素属于哪个集合，再使用交、并、补。", "example": "若 p 为假、q 为真，则 p → q 为真。若 A={a,b}，其幂集为 {∅,{a},{b},{a,b}}。", "pitfall": "不要把“p → q”误认为“q → p”；∅ 与 {∅} 不相同。", "questions": [{"q": "p → q 为假的条件是？", "options": ["p真q假", "p假q真", "p假q假"], "answer": "0", "why": "蕴含只有在前件真、后件假时为假。集合运算先辨明元素属于哪个集合，再使用交、并、补。"}, {"q": "含3个元素的集合，其幂集有多少个元素？", "answer": "8", "why": "每个元素都有选或不选两种状态，故 2³=8。"}]}, {"id": 1, "title": "二元关系", "start": 22, "end": 41, "group": "逻辑与集合", "intro": "关系是笛卡尔积的子集，用有序对描述元素间的联系。", "formula": "R ⊆ A × A；等价关系 = 自反 + 对称 + 传递", "body": "检查性质时逐条量化：自反检查每个 (a,a)，对称检查反向对，传递检查两段关系的合成。偏序用反对称替代对称。", "example": "整数上的同余模3是等价关系，等价类由余数0、1、2划分。", "pitfall": "反对称不是“不对称”：它允许 (a,a)。", "questions": [{"q": "等价关系必须具有？", "options": ["反自反性", "对称性", "反对称性"], "answer": "1", "why": "检查性质时逐条量化：自反检查每个 (a,a)，对称检查反向对，传递检查两段关系的合成。偏序用反对称替代对称。"}, {"q": "模3同余把整数划分为几个等价类？", "answer": "3", "why": "三个余数对应三个等价类。"}]}, {"id": 2, "title": "函数", "start": 42, "end": 47, "group": "逻辑与集合", "intro": "函数给定义域中每个元素指定唯一的像；值域未必等于陪域。", "formula": "双射 = 单射 + 满射", "body": "单射要求不同输入对应不同输出；满射要求陪域每个元素都有原像。只有双射才存在双侧逆函数。", "example": "f:ℤ→ℤ，f(x)=x+1 是双射，逆映射为 y↦y−1。", "pitfall": "判断满射必须先知道陪域。", "questions": [{"q": "f:ℤ→ℤ，f(x)=2x 是？", "options": ["双射", "满射非单射", "单射非满射"], "answer": "2", "why": "单射要求不同输入对应不同输出；满射要求陪域每个元素都有原像。只有双射才存在双侧逆函数。"}, {"q": "3元集合到2元集合共有多少个函数？", "answer": "8", "why": "每个输入有2种输出选择，共 2³ 个。"}]}, {"id": 3, "title": "自然数", "start": 48, "end": 60, "group": "逻辑与集合", "intro": "以归纳与递归刻画自然数，建立对无限多个命题的证明方法。", "formula": "基础步骤 + 归纳步骤 ⇒ 对所有自然数成立", "body": "先验证起点，再假设 n=k 成立并推出 n=k+1 成立。递归定义必须给出初值和递推规则。", "example": "求和 S₁=1，Sₙ₊₁=Sₙ+(n+1)，可归纳得到 Sₙ=n(n+1)/2。", "pitfall": "归纳假设只能作为推向下一步的条件，不能直接假设结论对所有 n 成立。", "questions": [{"q": "数学归纳法必须包含？", "options": ["只验证前十项", "基础与归纳步骤", "只写递推式"], "answer": "1", "why": "先验证起点，再假设 n=k 成立并推出 n=k+1 成立。递归定义必须给出初值和递推规则。"}, {"q": "1+2+…+10 等于多少？", "answer": "55", "why": "代入 n(n+1)/2 得 10×11/2=55。"}]}, {"id": 4, "title": "基数", "start": 61, "end": 81, "group": "逻辑与集合", "intro": "用双射比较集合大小；无限集合也有不同层级的大小。", "formula": "|ℕ| = |ℤ| = |ℚ| = ℵ₀；|P(A)| > |A|", "body": "有限集合通过计数比较；无限集合通过构造双射判断等势。可数无穷表示能与自然数建立双射。", "example": "自然数与偶数一一对应 n↦2n，因此真子集可以与原集合等势。", "pitfall": "无穷集合不能直接套用有限集合“真子集一定更小”的直觉。", "questions": [{"q": "下列哪个集合不可数？", "options": ["整数", "有理数", "实数"], "answer": "2", "why": "有限集合通过计数比较；无限集合通过构造双射判断等势。可数无穷表示能与自然数建立双射。"}, {"q": "5元集合的幂集的基数为多少？", "answer": "32", "why": "有限情形 |P(A)|=2⁵=32。"}]}, {"id": 5, "title": "图", "start": 82, "end": 119, "group": "图论", "intro": "用顶点和边刻画对象与联系，先区分有向、无向、简单图和多重图。", "formula": "Σ deg(v) = 2|E|", "body": "无向图每条边贡献两次度数；环贡献2。连通表示任意两顶点间存在路径。", "example": "若无向图有6条边，则所有顶点度数之和为12。奇度顶点的个数一定为偶数。", "pitfall": "度数和公式适用于无向图；有向图分别统计入度和出度。", "questions": [{"q": "无向图奇度顶点个数一定是？", "options": ["奇数", "偶数", "质数"], "answer": "1", "why": "无向图每条边贡献两次度数；环贡献2。连通表示任意两顶点间存在路径。"}, {"q": "完全图 K₅ 有多少条边？", "answer": "10", "why": "每对不同顶点恰有一条边，5×4/2=10。"}]}, {"id": 6, "title": "欧拉图与哈密顿图", "start": 120, "end": 126, "group": "图论", "intro": "欧拉问题关注每条边；哈密顿问题关注每个顶点。", "formula": "连通无向图有欧拉回路 ⇔ 所有顶点度数均为偶数", "body": "在含边且忽略孤立点的图中，非零度顶点连通是欧拉判定的前提。恰有两个奇度顶点时有开放欧拉通路。", "example": "环图 C₄ 既有欧拉回路，也有哈密顿回路；二者关注的对象不同。", "pitfall": "所有度数为偶数不能单独推出全图连通。", "questions": [{"q": "欧拉回路要求恰好经过一次的是？", "options": ["每条边", "每个顶点", "每个面"], "answer": "0", "why": "在含边且忽略孤立点的图中，非零度顶点连通是欧拉判定的前提。恰有两个奇度顶点时有开放欧拉通路。"}, {"q": "连通无向图有开放欧拉通路时，奇度顶点有几个？", "answer": "2", "why": "开放通路的起点和终点为两个奇度顶点。"}]}, {"id": 7, "title": "树", "start": 127, "end": 136, "group": "图论", "intro": "树是连通且无圈的无向图，是最精简的连通结构。", "formula": "树：|E| = |V| − 1", "body": "树中任意两顶点间存在唯一简单路径。删去任一条边会断开；加入一条新边会产生唯一的圈。", "example": "6个顶点的树有5条边。生成树保留原图全部顶点，只选取维持连通所需的边。", "pitfall": "仅有 n−1 条边并不足以判断树，还需连通或无圈条件。", "questions": [{"q": "树中任意两点之间的简单路径有？", "options": ["0条", "唯一1条", "至少2条"], "answer": "1", "why": "树中任意两顶点间存在唯一简单路径。删去任一条边会断开；加入一条新边会产生唯一的圈。"}, {"q": "10个顶点的树有多少条边？", "answer": "9", "why": "树的边数为顶点数减1。"}]}, {"id": 8, "title": "图的矩阵表示", "start": 137, "end": 147, "group": "图论", "intro": "把图转换为矩阵，从而用代数方式研究相邻、关联与游走。", "formula": "(Aᵏ)ᵢⱼ = 从 i 到 j 长度为 k 的游走数", "body": "简单图的邻接矩阵用0和1记录边。无向图矩阵对称；矩阵乘法的求和对应中间顶点选择。", "example": "三角形的邻接矩阵对角线为0，其平方的每个对角元为2。", "pitfall": "Aᵏ 统计游走，允许重复顶点和边，不一定是简单路径。", "questions": [{"q": "简单无向图的邻接矩阵一定？", "options": ["对称", "可逆", "全为1"], "answer": "0", "why": "简单图的邻接矩阵用0和1记录边。无向图矩阵对称；矩阵乘法的求和对应中间顶点选择。"}, {"q": "三角形中从固定顶点出发又回到该点，长度2的游走有几条？", "answer": "2", "why": "可以通过另外两个顶点分别往返。"}]}, {"id": 9, "title": "平面图", "start": 148, "end": 158, "group": "图论", "intro": "可平面图能画在平面上使边只在端点相交；平面图是这样的具体嵌入。", "formula": "连通平面图：v − e + f = 2", "body": "面数包含无界的外部面。简单平面图 v≥3 时有 e≤3v−6；不含三角形时可加强为 e≤2v−4。", "example": "一个三角形有3个顶点、3条边和2个面，满足3−3+2=2。", "pitfall": "满足边数上界只是必要条件，不能据此直接断定可平面。", "questions": [{"q": "欧拉公式的面数是否包括外部面？", "options": ["包括", "不包括", "只算外部面"], "answer": "0", "why": "面数包含无界的外部面。简单平面图 v≥3 时有 e≤3v−6；不含三角形时可加强为 e≤2v−4。"}, {"q": "连通平面图 v=6，e=9，则 f 为多少？", "answer": "5", "why": "由 f=2−v+e=5。"}]}, {"id": 10, "title": "图的着色", "start": 159, "end": 168, "group": "图论", "intro": "正常顶点着色要求相邻顶点使用不同颜色，最少颜色数称为色数。", "formula": "χ(Kₙ)=n；非空边二部图的色数为2", "body": "先寻找团获得色数下界，再构造具体着色获得上界。奇环需要3色，偶环需要2色。", "example": "C₅ 无法交替使用两种颜色闭合，增加第三种颜色后即可正常着色。", "pitfall": "独立顶点可以同色；颜色编号不影响着色有效性。", "questions": [{"q": "C₅ 的色数是？", "options": ["2", "3", "5"], "answer": "1", "why": "先寻找团获得色数下界，再构造具体着色获得上界。奇环需要3色，偶环需要2色。"}, {"q": "K₄ 的色数是多少？", "answer": "4", "why": "完全图任意两顶点相邻，四个顶点必须使用四种颜色。"}]}, {"id": 11, "title": "支配集、覆盖集与独立集", "start": 169, "end": 187, "group": "图论", "intro": "用顶点或边的子集刻画覆盖、互不相邻与匹配等优化问题。", "formula": "顶点覆盖的补集是独立集", "body": "顶点覆盖使每条边至少有一个端点入选；独立集中的点两两不相邻；匹配中的边两两不共享端点。", "example": "三角形最小顶点覆盖大小为2，最大独立集大小为1，最大匹配大小为1。", "pitfall": "极大指无法再扩充；最大指在所有可行集合中大小最大。", "questions": [{"q": "匹配中的任意两条边？", "options": ["必须相邻", "不能共享端点", "必须形成圈"], "answer": "1", "why": "顶点覆盖使每条边至少有一个端点入选；独立集中的点两两不相邻；匹配中的边两两不共享端点。"}, {"q": "K₃ 的最小顶点覆盖大小是多少？", "answer": "2", "why": "选两点即可覆盖三条边，只选一点会漏掉对边。"}]}, {"id": 12, "title": "代数系统", "start": 188, "end": 200, "group": "代数结构", "intro": "代数系统由非空集合与其上的运算组成，先检查运算是否封闭。", "formula": "二元运算：A × A → A", "body": "运算满足封闭之后，再检查结合律、交换律、单位元和逆元。不同性质需要分别验证。", "example": "整数上的加法封闭，具有结合律、交换律，单位元为0；正整数上的减法不封闭。", "pitfall": "交换律不等同于结合律，单位元也不同于零元（吸收元）。", "questions": [{"q": "整数集合上的减法是否封闭？", "options": ["是", "否", "仅正数时是"], "answer": "0", "why": "运算满足封闭之后，再检查结合律、交换律、单位元和逆元。不同性质需要分别验证。"}, {"q": "整数加法的单位元是多少？", "answer": "0", "why": "对任意整数 a，有 a+0=0+a=a。"}]}, {"id": 13, "title": "群", "start": 201, "end": 232, "group": "代数结构", "intro": "群是在结合运算下具有单位元且每个元素均有逆元的非空集合。", "formula": "有限群中：|H| 整除 |G|（H 为子群）", "body": "半群要求结合律；独异点（幺半群）再有单位元；群再要求每个元素可逆。交换群额外满足交换律。", "example": "模6加法群中元素2的阶是3，因为2+2+2≡0 (mod 6)。", "pitfall": "拉格朗日定理的逆命题对一般有限群并不成立。", "questions": [{"q": "群必定具有哪项性质？", "options": ["交换律", "每个元素有逆元", "只有有限个元素"], "answer": "1", "why": "半群要求结合律；独异点（幺半群）再有单位元；群再要求每个元素可逆。交换群额外满足交换律。"}, {"q": "模6加法群中元素2的阶是多少？", "answer": "3", "why": "最小正整数 k 使 2k≡0 (mod 6)，故 k=3。"}]}, {"id": 14, "title": "环与域", "start": 233, "end": 244, "group": "代数结构", "intro": "环将加法群与乘法结合在一起；域中每个非零元素都有乘法逆元。", "formula": "ℤₚ 是域 ⇔ p 为素数（p≥2）", "body": "环的加法构成交换群，乘法结合并满足对加法的分配律。是否要求乘法单位元应留意教材约定。", "example": "模5中2的乘法逆元为3，因为2×3≡1 (mod 5)。模6中2没有乘法逆元。", "pitfall": "域的零元素没有乘法逆元；不能在一般环中随意约去非零因子。", "questions": [{"q": "下面哪个是域？", "options": ["ℤ₆", "ℤ₅", "ℤ"], "answer": "1", "why": "环的加法构成交换群，乘法结合并满足对加法的分配律。是否要求乘法单位元应留意教材约定。"}, {"q": "模5中2的乘法逆元为多少？", "answer": "3", "why": "2×3=6≡1 (mod 5)。"}]}, {"id": 15, "title": "格与布尔代数", "start": 245, "end": 255, "group": "代数结构", "intro": "格是每对元素都有最小上界和最大下界的偏序集。", "formula": "幂集格：交为交运算， 并为并运算", "body": "最小上界称为并，最大下界称为交。布尔代数是有补的有界分配格。", "example": "P({a,b}) 按包含关系排序是格；{a} 与 {b} 的最小上界是 {a,b}，最大下界是 ∅。", "pitfall": "上界可能有多个，最小上界若存在则唯一。", "questions": [{"q": "幂集格中的最大下界对应？", "options": ["并集", "交集", "差集"], "answer": "1", "why": "最小上界称为并，最大下界称为交。布尔代数是有补的有界分配格。"}, {"q": "P({a,b,c}) 这个布尔代数共有多少个元素？", "answer": "8", "why": "它的元素是所有子集，共2³个。"}]}, {"id": 16, "title": "初等数论", "start": 256, "end": 272, "group": "数论", "intro": "整除、素数、同余和欧几里得算法构成数论的基本语言。", "formula": "a ≡ b (mod m) ⇔ m 整除 a−b", "body": "辗转相除求最大公因数：不断以除数和余数替换原数对，直到余数为0。模逆存在当且仅当两数互素。", "example": "48=18×2+12，18=12+6，12=6×2，所以 gcd(48,18)=6。", "pitfall": "同余式两侧不能随意除以一个与模数不互素的数。", "questions": [{"q": "a 在模 m 下可逆的条件是？", "options": ["a大于m", "gcd(a,m)=1", "a为偶数"], "answer": "1", "why": "辗转相除求最大公因数：不断以除数和余数替换原数对，直到余数为0。模逆存在当且仅当两数互素。"}, {"q": "gcd(48,18) 等于多少？", "answer": "6", "why": "辗转相除的最后一个非零余数为6。"}]}];